-- 10. Provision Demo User Accounts in auth.users if running in a PostgreSQL environment with Supabase auth schema
DO $$
DECLARE
    admin_uid UUID := 'u0000000-0000-0000-0000-000000000001';
    student_uid UUID := 'u0000000-0000-0000-0000-000000000002';
BEGIN
    IF EXISTS (SELECT 1 FROM information_schema.tables WHERE table_schema = 'auth' AND table_name = 'users') THEN
        INSERT INTO auth.users (id, instance_id, email, encrypted_password, email_confirmed_at, raw_app_meta_data, raw_user_meta_data, role, aud)
        VALUES 
        (admin_uid, '00000000-0000-0000-0000-000000000000', 'admin@demo.edu', crypt('AdminPassword123!', gen_salt('bf')), NOW(), '{"provider":"email","providers":["email"]}', '{"full_name":"Dr. Ramesh Kumar (Admin)","college_id":"c0000000-0000-0000-0000-000000000001"}', 'authenticated', 'authenticated'),
        (student_uid, '00000000-0000-0000-0000-000000000000', 'student@demo.edu', crypt('StudentPassword123!', gen_salt('bf')), NOW(), '{"provider":"email","providers":["email"]}', '{"full_name":"Priya Sharma (Student)","college_id":"c0000000-0000-0000-0000-000000000001"}', 'authenticated', 'authenticated')
        ON CONFLICT (id) DO NOTHING;

        -- Promote the admin user explicitly in public.profiles
        UPDATE public.profiles SET role = 'admin' WHERE id = admin_uid;
    END IF;
END $$;

COMMIT;
